#include <queue>
#include <iostream>

void safe_access(std::queue<int>& q) {
    if (q.empty()) {
        // Handle empty case gracefully
        return;
    }

    // Safe access and modification
    int& last = q.back();
    last = 99; 

    std::cout << "Front: " << q.front() 
              << ", Back: " << q.back() << std::endl;
}

// q.front(); // UNDEFINED BEHAVIOR if q is empty!
